    "That is the most for {group}. Untick one first.": {"es": "Es el máximo para {group}. Desmarca uno primero.", "it": "Questo è il massimo per {group}. Togli prima la spunta a uno.", "de": "Das ist das Maximum für {group}. Nimm zuerst einen Haken raus.", "fr": "C'est le maximum pour {group}. Décochez-en un d'abord.", "tr": "{group} için en fazla bu kadar. Önce birinin işaretini kaldır.", "sr-Latn-RS": "To je najviše za {group}. Prvo odznačite jedno.", "pl": "To maksimum dla grupy {group}. Najpierw odznacz coś.", "nl": "Dat is het maximum voor {group}. Vink er eerst een uit.", "cs": "To je maximum pro {group}. Nejdřív jedno odškrtněte.", "he": "זה המקסימום עבור {group}. קודם מבטלים סימון של אחד.", "ar": "هذا هو الحد الأقصى لـ {group}. ألغِ تحديد عنصر أولًا.", "pt": "Esse é o máximo para {group}. Desmarque um primeiro.", "ro": "Acesta e maximul pentru {group}. Debifează mai întâi unul.", "zh-CN": "{group}已达到上限。请先取消勾选一项。"},
    "Connected to {host}. Tick what shows on the TV.": {"es": "Conectado a {host}. Marca lo que se muestra en el televisor.", "es-MX": "Conectado a {host}. Marca lo que se muestra en la TV.", "it": "Connesso a {host}. Spunta cosa appare sulla TV.", "de": "Verbunden mit {host}. Hak an, was der Fernseher zeigt.", "fr": "Connecté à {host}. Cochez ce qui s'affiche sur la TV.", "tr": "Bağlandı: {host}. TV'de görünecekleri işaretle.", "sr-Latn-RS": "Povezano sa {host}. Označite šta se prikazuje na televizoru.", "pl": "Połączono z {host}. Zaznacz, co ma pokazywać telewizor.", "nl": "Verbonden met {host}. Vink aan wat de tv toont.", "cs": "Připojeno k {host}. Zaškrtněte, co se ukáže na televizi.", "he": "מחובר ל-\u2066{host}\u2069. מסמנים מה יוצג בטלוויזיה.", "ar": "تم الاتصال بـ \u2066{host}\u2069. حدّد ما يظهر على التلفزيون.", "pt": "Conectado a {host}. Marque o que aparece na TV.", "ro": "Conectat la {host}. Bifează ce apare pe televizor.", "zh-CN": "已连接到 {host}。勾选要在电视上显示的内容。"},
    "Saved. 1 thing shows on the TV now.": {"es": "Guardado. Ahora se muestra 1 cosa en el televisor.", "es-MX": "Guardado. Ahora se muestra 1 cosa en la TV.", "it": "Salvato. Ora sulla TV appare 1 elemento.", "de": "Gespeichert. Jetzt zeigt der Fernseher 1 Sache.", "fr": "Enregistré. 1 élément s'affiche maintenant sur la TV.", "tr": "Kaydedildi. TV'de şimdi 1 şey görünüyor.", "sr-Latn-RS": "Sačuvano. Na televizoru se sada prikazuje 1 stvar.", "pl": "Zapisano. Na telewizorze widać teraz 1 rzecz.", "nl": "Opgeslagen. Er staat nu 1 ding op de tv.", "cs": "Uloženo. Na televizi se teď ukazuje 1 věc.", "he": "נשמר. פריט 1 מוצג עכשיו בטלוויזיה.", "ar": "تم الحفظ. يظهر الآن عنصر 1 على التلفزيون.", "pt": "Salvo. 1 item aparece na TV agora.", "ro": "Salvat. Acum apare 1 element pe televizor.", "zh-CN": "已保存。电视上现在显示 1 项内容。"},
    "Saved. {n} things show on the TV now.": {"es": "Guardado. Ahora se muestran {n} cosas en el televisor.", "es-MX": "Guardado. Ahora se muestran {n} cosas en la TV.", "it": "Salvato. Ora sulla TV appaiono {n} elementi.", "de": "Gespeichert. Jetzt zeigt der Fernseher {n} Sachen.", "fr": "Enregistré. {n} éléments s'affichent maintenant sur la TV.", "tr": "Kaydedildi. TV'de şimdi {n} şey görünüyor.", "sr-Latn-RS": "Sačuvano. Broj stvari na televizoru: {n}.", "pl": "Zapisano. Liczba rzeczy widocznych teraz na telewizorze: {n}.", "nl": "Opgeslagen. Er staan nu {n} dingen op de tv.", "cs": "Uloženo. Počet věcí na televizi: {n}.", "he": "נשמר. {n} פריטים מוצגים עכשיו בטלוויזיה.", "ar": "تم الحفظ. عدد العناصر المعروضة على التلفزيون الآن: {n}.", "pt": "Salvo. {n} itens aparecem na TV agora.", "ro": "Salvat. Acum apar {n} elemente pe televizor.", "zh-CN": "已保存。电视上现在显示 {n} 项内容。"},
    "Pair this phone": {"es": "Vincular este móvil", "es-MX": "Vincular este celular", "it": "Accoppia questo telefono", "de": "Dieses Handy koppeln", "fr": "Associer ce téléphone", "tr": "Bu telefonu eşle", "sr-Latn-RS": "Upari ovaj telefon", "pl": "Sparuj ten telefon", "nl": "Deze telefoon koppelen", "cs": "Spárovat tento telefon", "he": "התאמת הטלפון הזה", "ar": "إقران هذا الهاتف", "pt": "Parear este celular", "ro": "Asociază acest telefon", "zh-CN": "配对这部手机"},
    "Type the 6 digit code shown on the TV.": {"es": "Escribe el código de 6 dígitos que aparece en el televisor.", "es-MX": "Escribe el código de 6 dígitos que aparece en la TV.", "it": "Scrivi il codice di 6 cifre mostrato sulla TV.", "de": "Gib den 6-stelligen Code ein, der am Fernseher steht.", "fr": "Tapez le code à 6 chiffres affiché sur la TV.", "tr": "TV'de gösterilen 6 haneli kodu yaz.", "sr-Latn-RS": "Upišite šestocifreni kod prikazan na televizoru.", "pl": "Wpisz 6-cyfrowy kod widoczny na telewizorze.", "nl": "Typ de 6-cijferige code die op de tv staat.", "cs": "Napište 6místný kód zobrazený na televizi.", "he": "מקלידים את הקוד בן 6 הספרות שמוצג בטלוויזיה.", "ar": "اكتب الرمز المكوّن من 6 أرقام الظاهر على التلفزيون.", "pt": "Digite o código de 6 dígitos que aparece na TV.", "ro": "Scrie codul de 6 cifre afișat pe televizor.", "zh-CN": "输入电视上显示的 6 位数代码。"},
    "Code from the TV": {"es": "Código del televisor", "es-MX": "Código de la TV", "it": "Codice dalla TV", "de": "Code vom Fernseher", "fr": "Code de la TV", "tr": "TV'deki kod", "sr-Latn-RS": "Kod sa televizora", "pl": "Kod z telewizora", "nl": "Code van de tv", "cs": "Kód z televize", "he": "קוד מהטלוויזיה", "ar": "الرمز من التلفزيون", "pt": "Código da TV", "ro": "Codul de la televizor", "zh-CN": "电视上的代码"},
    "Pair": {"es": "Vincular", "it": "Accoppia", "de": "Koppeln", "fr": "Associer", "tr": "Eşle", "sr-Latn-RS": "Upari", "pl": "Sparuj", "nl": "Koppelen", "cs": "Spárovat", "he": "התאמה", "ar": "إقران", "pt": "Parear", "ro": "Asociază", "zh-CN": "配对"},
