    "{n} photos are on the TV now.": {"es": "Ya hay {n} fotos en el televisor.", "es-MX": "Ya hay {n} fotos en la TV.", "it": "Ora ci sono {n} foto sulla TV.", "de": "{n} Fotos sind jetzt auf dem Fernseher.", "fr": "{n} photos sont maintenant sur la TV.", "tr": "TV'de şimdi {n} fotoğraf var.", "sr-Latn-RS": "Broj fotografija na televizoru: {n}.", "pl": "Liczba zdjęć na telewizorze: {n}.", "nl": "Er staan nu {n} foto's op de tv.", "cs": "Počet fotek na televizi: {n}.", "he": "{n} תמונות נמצאות עכשיו בטלוויזיה.", "ar": "عدد الصور على التلفزيون الآن: {n}.", "pt": "{n} fotos estão na TV agora.", "ro": "{n} fotografii sunt acum pe televizor.", "zh-CN": "电视上现在有 {n} 张照片。"},
    "One photo is on the TV now. {bad} could not be added.": {"es": "Ya hay una foto en el televisor. {bad} no se pudieron añadir.", "es-MX": "Ya hay una foto en la TV. {bad} no se pudieron agregar.", "it": "Ora c'è una foto sulla TV. Non è stato possibile aggiungerne {bad}.", "de": "Ein Foto ist jetzt auf dem Fernseher. {bad} konnten nicht hinzugefügt werden.", "fr": "Une photo est maintenant sur la TV. Impossible d'en ajouter {bad}.", "tr": "TV'de şimdi bir fotoğraf var. Eklenemeyen: {bad}.", "sr-Latn-RS": "Jedna fotografija je sada na televizoru. Nije moglo da se doda: {bad}.", "pl": "Na telewizorze jest teraz jedno zdjęcie. Nie udało się dodać: {bad}.", "nl": "Er staat nu één foto op de tv. {bad} konden niet worden toegevoegd.", "cs": "Na televizi je teď jedna fotka. Nepodařilo se přidat: {bad}.", "he": "תמונה אחת נמצאת עכשיו בטלוויזיה. לא היה אפשר להוסיף {bad}.", "ar": "توجد صورة واحدة على التلفزيون الآن. تعذّرت إضافة {bad}.", "pt": "Uma foto está na TV agora. {bad} não puderam ser adicionadas.", "ro": "O fotografie e acum pe televizor. {bad} nu au putut fi adăugate.", "zh-CN": "电视上现在有一张照片。有 {bad} 张无法添加。"},
    "{n} photos are on the TV now. {bad} could not be added.": {"es": "Ya hay {n} fotos en el televisor. {bad} no se pudieron añadir.", "es-MX": "Ya hay {n} fotos en la TV. {bad} no se pudieron agregar.", "it": "Ora ci sono {n} foto sulla TV. Non è stato possibile aggiungerne {bad}.", "de": "{n} Fotos sind jetzt auf dem Fernseher. {bad} konnten nicht hinzugefügt werden.", "fr": "{n} photos sont maintenant sur la TV. Impossible d'en ajouter {bad}.", "tr": "TV'de şimdi {n} fotoğraf var. Eklenemeyen: {bad}.", "sr-Latn-RS": "Broj fotografija na televizoru: {n}. Nije moglo da se doda: {bad}.", "pl": "Liczba zdjęć na telewizorze: {n}. Nie udało się dodać: {bad}.", "nl": "Er staan nu {n} foto's op de tv. {bad} konden niet worden toegevoegd.", "cs": "Počet fotek na televizi: {n}. Nepodařilo se přidat: {bad}.", "he": "{n} תמונות נמצאות עכשיו בטלוויזיה. לא היה אפשר להוסיף {bad}.", "ar": "عدد الصور على التلفزيون الآن: {n}. تعذّرت إضافة {bad}.", "pt": "{n} fotos estão na TV agora. {bad} não puderam ser adicionadas.", "ro": "{n} fotografii sunt acum pe televizor. {bad} nu au putut fi adăugate.", "zh-CN": "电视上现在有 {n} 张照片。有 {bad} 张无法添加。"},
    "No photos were added. {why}": {"es": "No se añadió ninguna foto. {why}", "es-MX": "No se agregó ninguna foto. {why}", "it": "Nessuna foto è stata aggiunta. {why}", "de": "Es wurden keine Fotos hinzugefügt. {why}", "fr": "Aucune photo n'a été ajoutée. {why}", "tr": "Hiç fotoğraf eklenmedi. {why}", "sr-Latn-RS": "Nijedna fotografija nije dodata. {why}", "pl": "Nie dodano żadnych zdjęć. {why}", "nl": "Er zijn geen foto's toegevoegd. {why}", "cs": "Nebyly přidány žádné fotky. {why}", "he": "לא נוספו תמונות. {why}", "ar": "لم تُضَف أي صور. {why}", "pt": "Nenhuma foto foi adicionada. {why}", "ro": "Nu a fost adăugată nicio fotografie. {why}", "zh-CN": "没有添加任何照片。{why}"},
