    "Saved. The TV shows the weather for {place} now.": {"es": "Guardado. El televisor ya muestra el tiempo de {place}.", "es-MX": "Guardado. La TV ya muestra el clima de {place}.", "it": "Salvato. Ora la TV mostra il meteo di {place}.", "de": "Gespeichert. Der Fernseher zeigt jetzt das Wetter für {place}.", "fr": "Enregistré. La TV affiche maintenant la météo de {place}.", "tr": "Kaydedildi. TV artık şu yerin hava durumunu gösteriyor: {place}.", "sr-Latn-RS": "Sačuvano. Televizor sada prikazuje vremensku prognozu za {place}.", "pl": "Zapisano. Telewizor pokazuje teraz pogodę dla: {place}.", "nl": "Opgeslagen. De tv toont nu het weer voor {place}.", "cs": "Uloženo. Televize teď ukazuje počasí pro {place}.", "he": "נשמר. הטלוויזיה מציגה עכשיו את מזג האוויר עבור {place}.", "ar": "تم الحفظ. يعرض التلفزيون الآن الطقس في {place}.", "pt": "Salvo. A TV agora mostra a previsão do tempo de {place}.", "ro": "Salvat. Televizorul arată acum vremea pentru {place}.", "zh-CN": "已保存。电视现在显示 {place} 的天气。"},
    "Saved. The TV shows {place} now.": {"es": "Guardado. El televisor ya muestra {place}.", "es-MX": "Guardado. La TV ya muestra {place}.", "it": "Salvato. Ora la TV mostra {place}.", "de": "Gespeichert. Der Fernseher zeigt jetzt {place}.", "fr": "Enregistré. La TV affiche maintenant {place}.", "tr": "Kaydedildi. TV artık şunu gösteriyor: {place}.", "sr-Latn-RS": "Sačuvano. Televizor sada prikazuje {place}.", "pl": "Zapisano. Telewizor pokazuje teraz: {place}.", "nl": "Opgeslagen. De tv toont nu {place}.", "cs": "Uloženo. Televize teď ukazuje {place}.", "he": "נשמר. הטלוויזיה מציגה עכשיו את {place}.", "ar": "تم الحفظ. يعرض التلفزيون الآن {place}.", "pt": "Salvo. A TV agora mostra {place}.", "ro": "Salvat. Televizorul arată acum {place}.", "zh-CN": "已保存。电视现在显示 {place}。"},
